def histogram(test):
    """Given a string representing space-separated lowercase letters, return a dictionary
    of the letter(s) with the most repetition and their corresponding count(s).

    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """

    # Split the input string into a list of characters and count their occurrences using a dictionary
    char_count = {char: test.count(char) for char in set(test)}

    # Return the dictionary with the maximum value(s) as key(s)
    return dict(sorted(char_count.items(), key=lambda item: item[1], reverse=True))
```

