    return n % 11 == 0

def is_multiple_of_thirteen(n):
    return n % 13 == 0

def count_digit_seven(n):
    count = 0
    while n > 0:
        digit = n % 10
        if digit == 7:
            count += 1
        n //= 10
    return count

def fizz_buzz(n):
    count = 0
    for i in range(int(math.floor(0.1 * n)), n):
        if is_multiple_of_eleven(i) or is_multiple_of_thirteen(i):
            count += count_digit_seven(i)
    return count

