def triples_sum_to_zero(numbers):
    """
    Returns True if there are three distinct elements in the list that sum to zero,
    and False otherwise.
    """
    numbers.sort()
    n = len(numbers)
    for i in range(n - 2):
        if numbers[i] + numbers[i+1] + numbers[i+2] > 0:
            continue
        low, high = i+1, n-1
        while low < high:
            if numbers[i] + numbers[low] + numbers[high] == 0:
                return True
            if numbers[i] + numbers[low] + numbers[high] > 0:
                low += 1
            else:
                high -= 1
    return False

