def rotate(string, n):
    """Rotates a string by n positions."""
    return string[-n:] + string[:-n]

def cycpattern_check(a, b):
    """Checks if the second word or any of its rotations is a substring in the first word."""

    # Check if the second word is a substring of the first word
    if b in a:
        return True

    # Check if any rotation of the second word is a substring of the first word
    for i in range(len(b)):
        rotation = rotate(b, i)
        if rotation in a:
            return True

    return False

